//! Generated by `series.py gen`: the κ tables of a box's series (see series.py).

use crate::geom::V;

pub const K2: [[f64; 3]; 3] = [[1.0, -0.5, -0.5], [-0.5, 1.0, -0.5], [-0.5, -0.5, 1.0]];
pub const E2: [[i32; 3]; 3] = [[2, 0, 0], [0, 2, 0], [0, 0, 2]];
pub const K4: [[f64; 6]; 6] = [[1.0, -3.0, -3.0, 0.375, 0.75, 0.375], [-3.0, 20.25, -2.25, -3.0, -2.25, 0.75], [-3.0, -2.25, 20.25, 0.75, -2.25, -3.0], [0.375, -3.0, 0.75, 1.0, -3.0, 0.375], [0.75, -2.25, -2.25, -3.0, 20.25, -3.0], [0.375, 0.75, -3.0, 0.375, -3.0, 1.0]];
pub const E4: [[i32; 3]; 6] = [[4, 0, 0], [2, 2, 0], [2, 0, 2], [0, 4, 0], [0, 2, 2], [0, 0, 4]];
pub const K6: [[f64; 10]; 10] = [[1.0, -7.5, -7.5, 5.625, 11.25, 5.625, -0.3125, -0.9375, -0.9375, -0.3125], [-7.5, 108.75, 3.75, -94.6875, -84.375, 10.3125, 5.625, 10.3125, 3.75, -0.9375], [-7.5, 3.75, 108.75, 10.3125, -84.375, -94.6875, -0.9375, 3.75, 10.3125, 5.625], [5.625, -94.6875, 10.3125, 108.75, -84.375, 3.75, -7.5, 3.75, 10.3125, -0.9375], [11.25, -84.375, -84.375, -84.375, 1012.5, -84.375, 11.25, -84.375, -84.375, 11.25], [5.625, 10.3125, -94.6875, 3.75, -84.375, 108.75, -0.9375, 10.3125, 3.75, -7.5], [-0.3125, 5.625, -0.9375, -7.5, 11.25, -0.9375, 1.0, -7.5, 5.625, -0.3125], [-0.9375, 10.3125, 3.75, 3.75, -84.375, 10.3125, -7.5, 108.75, -94.6875, 5.625], [-0.9375, 3.75, 10.3125, 10.3125, -84.375, 3.75, 5.625, -94.6875, 108.75, -7.5], [-0.3125, -0.9375, 5.625, -0.9375, 11.25, -7.5, -0.3125, 5.625, -7.5, 1.0]];
pub const E6: [[i32; 3]; 10] = [[6, 0, 0], [4, 2, 0], [4, 0, 2], [2, 4, 0], [2, 2, 2], [2, 0, 4], [0, 6, 0], [0, 4, 2], [0, 2, 4], [0, 0, 6]];

fn mu<const N: usize>(half: V, e: &[[i32; 3]; N]) -> [f64; N] {
    let mut out = [0.0; N];
    for (o, x) in out.iter_mut().zip(e) {
        *o = (0..3).map(|i| half[i].powi(x[i]) / f64::from(x[i] + 1)).product();
    }
    out
}

fn fold<const N: usize>(mu: [f64; N], k: &[[f64; N]; N]) -> [f64; N] {
    let mut out = [0.0; N];
    for (e, m) in mu.iter().enumerate() {
        for f in 0..N {
            out[f] += m * k[e][f];
        }
    }
    out
}

/// β for l = 2, 4, 6 of a box with half-sides `half` (m).
pub fn betas(half: V) -> ([f64; 3], [f64; 6], [f64; 10]) {
    (fold(mu(half, &E2), &K2), fold(mu(half, &E4), &K4), fold(mu(half, &E6), &K6))
}
